def _key(units):
    return hashlib.sha1(struct.pack('<%dH' % len(units), *units)).hexdigest()[:16]


def apply(entry, string_index, units):
    """Return (new_units, status). status is None when this (entry, string) has
    no row (units unchanged, not counted); True when the fan source hash matched
    and the rewrite was applied; False when the source hash did not match (a
    different build of this row) - units are left untouched and the caller
    counts a fallback."""
    row = REWRITE.get((entry, string_index))
    if row is None:
        return units, None
    u = list(units)
    if _key(u) != row['hash']:
        return units, False
    new = list(row['units'])
    if _key(new) != row['want']:
        return units, False
    return new, True


def patch_entry(entry_id, entry_bytes):
    """Apply every REWRITE row that belongs to this entry. Returns
    (new_bytes, applied, fallback); every existing string's tail (spt.tails)
    is carried over unchanged - rebuilding an spt entry without passing
    tails= silently zeroes another, untouched string's own terminator slot
    (audit_tails is what catches that class of defect, so every call here
    passes tails= explicitly rather than relying on build_ds's None default)."""
    rows = [si for (ei, si) in REWRITE if ei == entry_id]
    if not rows or not entry_bytes or entry_bytes[:4] != b' TPS':
        return entry_bytes, 0, 0
    h = parse(entry_bytes, True)[0]
    keep = spt_tails(entry_bytes, True)
    S = list(all_strings(entry_bytes, True))
    changed = fallback = 0
    new = []
    for si, a, _ln, u in S:
        nu, status = apply(entry_id, si, u) if si in rows else (u, None)
        new.append((a, list(nu)))
        if status is True:
            changed += 1
        elif status is False:
            fallback += 1
    if not changed:
        return entry_bytes, 0, fallback
    return (build_ds(new[0][1], new[1:], h['term'], h['scale'], h['last'], tails=keep),
            changed, fallback)
